import React from "react";

const Navbar = () => {
  return (
    <nav
      style={{
        padding: "18px",
        background: "linear-gradient(90deg, #000000, #434343)",
        color: "white",
        textAlign: "center",
        fontSize: "22px",
        fontWeight: "600",
        boxShadow: "0 4px 12px rgba(0,0,0,0.3)"
      }}
    >
      Customer Churn Prediction System
    </nav>
  );
};

export default Navbar;
